uint256[] public chapterIds;
function chapterAt(uint256 index) external view returns (uint256) {
    require(index < chapterIds.length, "index out of bounds");
    return chapterIds[index];
}

pragma solidity ^0.8.20;
contract ChapterList {
    uint256[] public chapterIds;
    function add(uint256 id) external { chapterIds.push(id); }
    function count() external view returns (uint256) { return chapterIds.length; }
    function removeLast() external { require(chapterIds.length > 0, "empty"); chapterIds.pop(); }
}

